INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c3b3-7187-9335-d7c82660dbb5'::uuid, '019f9df7-a2a2-77cc-bb88-40ce254805a8'::uuid, 'A map is drawn to a scale of 1 : 50 000.

