INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a067f4-c3c9-7a9b-8a48-bc812e020bc7'::uuid, '019f9df7-a2a2-7853-96ff-2c02dc5e1f10'::uuid, 'Express as a single fraction in its simplest form:

2x/(x^2 - 4) + 5/(2 - x).', '(-3x - 10)/[(x - 2)(x + 2)]', '2x/(x^2 - 4) + 5/(2 - x)
= 2x/[(x - 2)(x + 2)] - 5/(x - 2)
= [2x - 5(x + 2)] / [(x - 2)(x + 2)]
= (-3x - 10) / [(x - 2)(x + 2)].', 'Medium', '{"tags":"sass-2022-p1,q10","subtopic":"Algebraic fractions","question_type":"open","diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-03T15:48:09.289Z'::timestamptz, '2026-09-03T15:48:09.289Z'::timestamptz) ON CONFLICT (id) DO NOTHING;